#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static bool prime(int x) {
    if (x < 2) return false;
    for (int d = 2; d * d <= x; d++)
        if (x % d == 0) return false;
    return true;
}
static string expected(const string& in) {
    istringstream iss(in);
    int a, b;
    iss >> a >> b;
    string out;
    for (int x = a; x <= b; x++) {
        int r = (x % 10) * 10 + x / 10;
        if (prime(x) && prime(r)) out += to_string(x) + "\n";
    }
    return out;
}
static bool normEq(const string& a, const string& b) {
    istringstream isa(a), isb(b);
    vector<string> la, lb;
    string line;
    while (getline(isa, line)) { while (!line.empty() && (line.back()==' '||line.back()=='\r')) line.pop_back(); la.push_back(line); }
    while (getline(isb, line)) { while (!line.empty() && (line.back()==' '||line.back()=='\r')) line.pop_back(); lb.push_back(line); }
    while (!la.empty() && la.back().empty()) la.pop_back();
    while (!lb.empty() && lb.back().empty()) lb.pop_back();
    return la == lb;
}
static bool check(const string& exe, const string& in, int id) {
    const string inF = "l4asmp1_in.txt", outF = "l4asmp1_out.txt";
    {
        ofstream o(inF);
        o << in;
    }
    int code = system((exe + " < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream fis(outF);
    string got((istreambuf_iterator<char>(fis)), istreambuf_iterator<char>());
    if (code != 0 || !normEq(got, expected(in))) {
        cout << "[FAIL] case " << id << ": status=" << code
             << ", actual=" << got.substr(0, 120) << ", expected=" << expected(in).substr(0, 120) << "\n";
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<string> fixedCases = {
        "11 20",
        "10 99",
        "12 19",
        "21 29",
        "10 11",
        "10 98",
    };
    for (size_t i = 0; i < fixedCases.size(); i++) {
        ++total;
        if (check(exe, fixedCases[i], 1 + i)) ++passed;
    }
    srand(20250630);
    for (int t = 0; t < 10; t++) {
        int a = 11 + rand() % 80, b = a + rand() % (99 - a);
        ++total;
        if (check(exe, to_string(a) + " " + to_string(b), 7 + t)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << "\n";
    return passed == total ? 0 : 1;
}

